            self.expect("OP", ")")
            return e
        raise SyntaxError_("表达式里出现意外的 %r" % (t,))

    def parse_cond(self):
        return self.parse_or()

    def parse_or(self):
        c = self.parse_and()
        while self.peek()[0] == "OP" and self.peek()[1] == "||":
            self.next()
            c = ("or", c, self.parse_and())
        return c

    def parse_and(self):
        c = self.parse_not()
        while self.peek()[0] == "OP" and self.peek()[1] == "&&":
            self.next()
            c = ("and", c, self.parse_not())
        return c

    def parse_not(self):
        if self.peek()[0] == "OP" and self.peek()[1] == "!":
            self.next()
            return ("not", self.parse_not())
        return self.parse_rel()

    def parse_rel(self):
        e1 = self.parse_expr()
        t = self.peek()
        if t[0] == "OP" and t[1] in ("==", "!=", "<", "<=", ">", ">="):
            self.next()
            return ("cmp", t[1], e1, self.parse_expr())
        raise SyntaxError_("条件里缺少比较运算符：%r" % (t,))

    def parse_int_literal(self):
        sign = 1
        if self.peek()[0] == "OP" and self.peek()[1] == "-":
            self.next()
            sign = -1
        return sign * self.expect("INT")[1]

    def parse_stmt(self):
        t = self.peek()
        if t[0] == "OP" and t[1] == "{":
            return self.parse_block()
        if t[0] != "ID":
            raise SyntaxError_("语句 %r 无法识别" % (t,))
        kw = t[1]
        if kw == "input":
            self.next()
            name = self.expect("ID")[1]
            self.expect("ID", "in")
            self.expect("OP", "[")
            lo = self.parse_int_literal()
            self.expect("OP", ",")
            hi = self.parse_int_literal()
            self.expect("OP", "]")
            self.expect("OP", ";")
            return ("input", name, lo, hi)
        if kw == "if":
            self.next()
            self.expect("OP", "(")
            cond = self.parse_cond()
            self.expect("OP", ")")
            then = self.parse_block()
            els = ("block", [])
            if self.peek()[0] == "ID" and self.peek()[1] == "else":
                self.next()
                els = self.parse_block()
            return ("if", cond, then, els)
        if kw == "while":
            self.next()
            self.expect("OP", "(")
            cond = self.parse_cond()
            self.expect("OP", ")")
            body = self.parse_block()
            return ("while", cond, body)
        if kw == "assert":
            self.next()
            self.expect("OP", "(")
            cond = self.parse_cond()
            self.expect("OP", ")")
            self.expect("OP", ";")
            return ("assert", cond)
        name = self.next()[1]
        self.expect("OP", "=")
        e = self.parse_expr()
        self.expect("OP", ";")
        return ("assign", name, e)

    def parse_block(self):
        self.expect("OP", "{")
        stmts = []
        while not (self.peek()[0] == "OP" and self.peek()[1] == "}"):
            if self.peek()[0] == "EOF":
                raise SyntaxError_("缺少 }")
            stmts.append(self.parse_stmt())
        self.expect("OP", "}")
        return ("block", stmts)

    def parse(self):
        stmts = []
        while self.peek()[0] != "EOF":
            stmts.append(self.parse_stmt())
        return ("block", stmts)


def parse(src):
    return Parser(src).parse()


class DivZero(Exception):
    pass


def trunc_div(a, b):
    q = abs(a) // abs(b)
    return q if (a >= 0) == (b >= 0) else -q


def eval_expr(e, env):
    t = e[0]
    if t == "int":
        return e[1]
    if t == "var":
        return env[e[1]]
    if t == "neg":
        return -eval_expr(e[1], env)
    if t == "binop":
        op, a, b = e[1], eval_expr(e[2], env), eval_expr(e[3], env)
        if op == "+":
            return a + b
        if op == "-":
            return a - b
        if op == "*":
            return a * b
        if op == "/":
            if b == 0:
                raise DivZero()
            return trunc_div(a, b)
    raise ValueError(e)


def eval_cond(c, env):
    t = c[0]
    if t == "cmp":
        op, a, b = c[1], eval_expr(c[2], env), eval_expr(c[3], env)
        return {"==": a == b, "!=": a != b, "<": a < b, "<=": a <= b,
                ">": a > b, ">=": a >= b}[op]
    if t == "not":
        return not eval_cond(c[1], env)
    if t == "and":
        return eval_cond(c[1], env) and eval_cond(c[2], env)
    if t == "or":
        return eval_cond(c[1], env) or eval_cond(c[2], env)
    raise ValueError(c)


def exec_stmts(stmts, env, max_iter=1000000):
    for s in stmts:
        k = s[0]
        if k == "input":
            _, name, lo, hi = s
            env[name] = env.get(name, 0)
        elif k == "assign":
            _, name, e = s
            env[name] = eval_expr(e, env)
        elif k == "if":
            _, cond, then, els = s
            branch = then if eval_cond(cond, env) else els
            r = exec_stmts(branch[1], env, max_iter)
            if r[0] != "ok":
                return r
        elif k == "while":
            _, cond, body = s
            it = 0
            while eval_cond(cond, env):
                it += 1
                if it > max_iter:
                    return ("loop", None)
                r = exec_stmts(body[1], env, max_iter)
                if r[0] != "ok":
                    return r
        elif k == "assert":
            _, cond = s
            if not eval_cond(cond, env):
                return ("assert", s)
        elif k == "block":
            r = exec_stmts(s[1], env, max_iter)
            if r[0] != "ok":
                return r
        else:
            raise ValueError(s)
    return ("ok", None)


def run_concrete(prog, inputs):
    env = dict(inputs)
    try:
        return exec_stmts(prog[1], env)
    except DivZero:
        return ("div", None)


def input_vars(prog):
    out = {}
    for s in prog[1]:
        if s[0] == "input":
            out[s[1]] = (s[2], s[3])
    return out


def ground_truth(prog):
    iv = input_vars(prog)
    names = list(iv.keys())
    ranges = [range(iv[n][0], iv[n][1] + 1) for n in names]
    for combo in itertools.product(*ranges):
        inputs = dict(zip(names, combo))
        r = run_concrete(prog, inputs)
        if r[0] in ("assert", "div"):
            return ("UNSAFE", inputs, r[0])
        if r[0] == "loop":
            return ("LOOP", inputs, None)
    return ("SAFE", None, None)


# ======================================================================
# 30 个测试程序（name, source, expected）
# ======================================================================

PROGRAMS = [
    ("bound_ge", "input x in [0,10]; assert(x >= 0);", "SAFE"),
    ("add_ge", "input x in [0,10]; y = x + 5; assert(y >= 5);", "SAFE"),
