def candidate_values(lo, hi):
    """有代表性的候选值。"""
    cands = []
    for v in (lo, hi, 0, 1, -1, lo+1, hi-1, (lo+hi)//2):
        if lo <= v <= hi and v not in cands:
            cands.append(v)
    random.seed(12345)
    extra = [random.randint(lo,hi) for _ in range(6)] if hi>lo else []
    for v in extra:
        if v not in cands: cands.append(v)
    return cands

